screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス（仮定：見積書関連データが tables[0] に存在）
  const estimateTableIndex = 0;
  const deviationTableIndex = 1;
  const autoJudgmentTableIndex = 2;

  // 現在選択中の見積書データ
  let currentEstimate = null;
  let currentDeviation = null;

  // DOM要素キャッシュ
  const searchInput = container.querySelector('[data-testid="estimate-id-search"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const originalImageContainer = container.querySelector('#original-image-container');
  const ocrProductName = container.querySelector('#ocr-product-name');
  const ocrQuantity = container.querySelector('#ocr-quantity');
  const ocrUnitPrice = container.querySelector('#ocr-unit-price');
  const ocrTotalAmount = container.querySelector('#ocr-total-amount');
  const checkProductName = container.querySelector('[data-testid="check-product-name"]');
  const checkQuantity = container.querySelector('[data-testid="check-quantity"]');
  const checkUnitPrice = container.querySelector('[data-testid="check-unit-price"]');
  const checkTotalAmount = container.querySelector('[data-testid="check-total-amount"]');
  const checkProductStatus = container.querySelector('#check-product-status');
  const checkQuantityStatus = container.querySelector('#check-quantity-status');
  const checkUnitPriceStatus = container.querySelector('#check-unit-price-status');
  const checkTotalStatus = container.querySelector('#check-total-status');
  const mismatchPanel = container.querySelector('#mismatch-panel');
  const correctionItemSelect = container.querySelector('[data-testid="correction-item-select"]');
  const correctionContent = container.querySelector('[data-testid="correction-content"]');
  const correctionReasonSelect = container.querySelector('[data-testid="correction-reason-select"]');
  const saveCorrectionBtn = container.querySelector('[data-testid="save-correction-button"]');
  const approveBtn = container.querySelector('[data-testid="approve-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  const estimateListModal = container.querySelector('#estimate-list-modal');
  const estimateListTbody = container.querySelector('#estimate-list-tbody');

  // 初期化：見積書一覧を取得
  async function initEstimateList() {
    const estimates = await window.aivicApi.list(estimateTableIndex);
    if (!estimates || estimates.length === 0) {
      estimateListTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">見積書データがありません</td></tr>';
      return;
    }
    renderEstimateList(estimates);
  }

  // 見積書一覧をテーブルで描画
  function renderEstimateList(estimates) {
    estimateListTbody.innerHTML = estimates.map(est => `
      <tr style="border-bottom: 1px solid var(--border); cursor: pointer;" data-id="${est.id}" onclick="selectEstimate(this)">
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${est.id || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${est.productName || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text);">${est.totalAmount ? '¥' + est.totalAmount.toLocaleString() : '-'}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="select-estimate-btn" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 3px; font-size: 11px; cursor: pointer;">選択</button>
        </td>
      </tr>
    `).join('');
  }

  // グローバルスコープに selectEstimate を登録
  window.selectEstimate = function(row) {
    const estimateId = row.dataset.id;
    loadEstimateData(estimateId);
    estimateListModal.style.display = 'none';
  };

  // 見積書データを読み込んで表示
  async function loadEstimateData(estimateId) {
    const estimates = await window.aivicApi.list(estimateTableIndex);
    currentEstimate = estimates.find(e => e.id === estimateId);

    if (!currentEstimate) {
      alert('見積書が見つかりません');
      return;
    }

    // 原本画像を表示（ダミー）
    originalImageContainer.innerHTML = `
      <div style="text-align: center; color: var(--text-muted);">
        <div style="font-size: 14px; margin-bottom: 8px;">📄 見積書ID: ${currentEstimate.id}</div>
        <div style="font-size: 12px; color: var(--text-muted);">原本画像表示エリア</div>
      </div>
    `;

    // OCR読取結果を表示
    ocrProductName.textContent = currentEstimate.productName || '-';
    ocrQuantity.textContent = currentEstimate.quantity || '-';
    ocrUnitPrice.textContent = currentEstimate.unitPrice ? '¥' + currentEstimate.unitPrice.toLocaleString() : '-';
    ocrTotalAmount.textContent = currentEstimate.totalAmount ? '¥' + currentEstimate.totalAmount.toLocaleString() : '-';

    // 乖離分析結果を取得
    const deviations = await window.aivicApi.list(deviationTableIndex);
    currentDeviation = deviations.find(d => d.estimateId === estimateId);

    // 検証ステータスを更新
    updateVerificationStatus();

    // 修正パネルをリセット
    mismatchPanel.style.display = 'none';
    correctionItemSelect.value = '';
    correctionContent.value = '';
    correctionReasonSelect.value = '';
  }

  // 検証ステータスを更新
  function updateVerificationStatus() {
    if (!currentEstimate || !currentDeviation) {
      checkProductStatus.textContent = '未検証';
      checkQuantityStatus.textContent = '未検証';
      checkUnitPriceStatus.textContent = '未検証';
      checkTotalStatus.textContent = '未検証';
      return;
    }

    // 簡易的な一致判定（実際にはより詳細なロジックが必要）
    const deviationRate = currentDeviation.deviationRate || 0;
    const status = deviationRate <= 5 ? '✓ 一致' : '✗ 不一致';
    const statusColor = deviationRate <= 5 ? '#4caf50' : '#f44336';

    checkProductStatus.textContent = status;
    checkProductStatus.style.color = statusColor;
    checkQuantityStatus.textContent = status;
    checkQuantityStatus.style.color = statusColor;
    checkUnitPriceStatus.textContent = status;
    checkUnitPriceStatus.style.color = statusColor;
    checkTotalStatus.textContent = status;
    checkTotalStatus.style.color = statusColor;

    // 不一致がある場合は修正パネルを表示
    if (deviationRate > 5) {
      mismatchPanel.style.display = 'block';
    }
  }

  // 検索ボタンのクリックハンドラ
  searchBtn.addEventListener('click', async () => {
    const searchId = searchInput.value.trim();
    if (!searchId) {
      estimateListModal.style.display = 'flex';
      initEstimateList();
      return;
    }

    const estimates = await window.aivicApi.list(estimateTableIndex);
    const filtered = estimates.filter(e => e.id.includes(searchId));

    if (filtered.length === 0) {
      alert('該当する見積書が見つかりません');
      return;
    }

    if (filtered.length === 1) {
      loadEstimateData(filtered[0].id);
    } else {
      renderEstimateList(filtered);
      estimateListModal.style.display = 'flex';
    }
  });

  // リセットボタンのクリックハンドラ
  resetBtn.addEventListener('click', () => {
    searchInput.value = '';
    currentEstimate = null;
    currentDeviation = null;
    originalImageContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px;"><div style="margin-bottom: 8px;">見積書を選択してください</div><div style="font-size: 11px; color: var(--text-muted);">画像がここに表示されます</div></div>';
    ocrProductName.textContent = '-';
    ocrQuantity.textContent = '-';
    ocrUnitPrice.textContent = '-';
    ocrTotalAmount.textContent = '-';
    checkProductStatus.textContent = '-';
    checkQuantityStatus.textContent = '-';
    checkUnitPriceStatus.textContent = '-';
    checkTotalStatus.textContent = '-';
    mismatchPanel.style.display = 'none';
    checkProductName.checked = false;
    checkQuantity.checked = false;
    checkUnitPrice.checked = false;
    checkTotalAmount.checked = false;
  });

  // 修正内容保存ボタンのクリックハンドラ
  saveCorrectionBtn.addEventListener('click', async () => {
    if (!currentEstimate) {
      alert('見積書を選択してください');
      return;
    }

    const item = correctionItemSelect.value;
    const content = correctionContent.value.trim();
    const reason = correctionReasonSelect.value;

    if (!item || !content || !reason) {
      alert('すべての項目を入力してください');
      return;
    }

    // 修正内容を保存（実装例）
    const correctionData = {
      estimateId: currentEstimate.id,
      correctionItem: item,
      correctionContent: content,
      correctionReason: reason,
      timestamp: new Date().toISOString()
    };

    // API経由で保存（テーブルインデックスは仮定）
    const saved = await window.aivicApi.save(deviationTableIndex, correctionData);
    if (saved) {
      alert('修正内容を保存しました');
      mismatchPanel.style.display = 'none';
      correctionItemSelect.value = '';
      correctionContent.value = '';
      correctionReasonSelect.value = '';
    }
  });

  // 検証完了・承認ボタンのクリックハンドラ
  approveBtn.addEventListener('click', async () => {
    if (!currentEstimate) {
      alert('見積書を選択してください');
      return;
    }

    const allChecked = checkProductName.checked && checkQuantity.checked && checkUnitPrice.checked && checkTotalAmount.checked;
    if (!allChecked) {
      alert('すべての検証項目をチェックしてください');
      return;
    }

    // 承認処理（実装例）
    const approvalData = {
      estimateId: currentEstimate.id,
      status: 'approved',
      verifiedAt: new Date().toISOString(),
      verifiedBy: 'current_user'
    };

    const saved = await window.aivicApi.save(autoJudgmentTableIndex, approvalData);
    if (saved) {
      alert('検証が完了し、承認しました');
      resetBtn.click();
    }
  });

  // キャンセルボタンのクリックハンドラ
  cancelBtn.addEventListener('click', () => {
    if (confirm('入力内容を破棄してもよろしいですか？')) {
      resetBtn.click();
    }
  });

  // モーダルの背景クリックで閉じる
  estimateListModal.addEventListener('click', (e) => {
    if (e.target === estimateListModal) {
      estimateListModal.style.display = 'none';
    }
  });

  // Escキーでモーダルを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && estimateListModal.style.display !== 'none') {
      estimateListModal.style.display = 'none';
    }
  });

  // 初期化
  initEstimateList();
}

function(container, apiUrl, tables) {
  const estimateSelect = container.querySelector('[data-testid="estimate-select"]');
  const logicSelect = container.querySelector('[data-testid="logic-select"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const checkDiffBtn = container.querySelector('[data-testid="check-diff-button"]');
  const runValidationBtn = container.querySelector('[data-testid="run-validation-button"]');
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  const assessorStatusSelect = container.querySelector('[data-testid="assessor-status"]');
  const assessorAmountInput = container.querySelector('[data-testid="assessor-amount"]');
  const judgmentCommentTextarea = container.querySelector('[data-testid="judgment-comment"]');
  const diffModal = container.querySelector('#diff-modal');
  const validationModal = container.querySelector('#validation-modal');

  // Load deviation analysis data
  async function loadDeviationData() {
    const rows = await window.aivicApi.list(0); // 乖離分析結果テーブル
    if (!rows) return;
    const tbody = container.querySelector('#deviation-tbody');
    tbody.innerHTML = '';
    rows.slice(0, 5).forEach(row => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      const deviationRate = row.乖離率 || 0;
      const color = deviationRate > 0 ? '#d97706' : '#059669';
      tr.innerHTML = `
        <td style="padding: 6px; color: var(--text);">${row.分析対象項目 || ''}</td>
        <td style="padding: 6px; text-align: right; color: var(--text);">¥${(row.見積値 || 0).toLocaleString()}</td>
        <td style="padding: 6px; text-align: right; color: var(--text);">¥${(row.参照値 || 0).toLocaleString()}</td>
        <td style="padding: 6px; text-align: right; color: ${color}; font-weight: 600;">${deviationRate > 0 ? '+' : ''}${deviationRate}%</td>
      `;
      tbody.appendChild(tr);
    });
  }

  // Search past projects
  searchBtn.addEventListener('click', async () => {
    const filterText = container.querySelector('[data-testid="project-filter"]').value;
    // In real scenario, filter past project data by filterText
    console.log('Searching past projects:', filterText);
  });

  // Check judgment difference
  checkDiffBtn.addEventListener('click', () => {
    const assessorStatus = assessorStatusSelect.value || '未入力';
    container.querySelector('#diff-assessor-status').textContent = assessorStatus;
    const assessorAmount = parseInt(assessorAmountInput.value) || 0;
    const autoAmount = 820000; // Example auto judgment amount
    const diffAmount = assessorAmount - autoAmount;
    container.querySelector('#diff-amount').textContent = `¥${diffAmount.toLocaleString()}`;
    diffModal.style.display = 'flex';
  });

  // Run logic validation
  runValidationBtn.addEventListener('click', () => {
    validationModal.style.display = 'flex';
  });

  // Save judgment
  saveBtn.addEventListener('click', async () => {
    const status = assessorStatusSelect.value;
    const amount = parseInt(assessorAmountInput.value);
    const comment = judgmentCommentTextarea.value;
    if (!status || !amount) {
      alert('判定ステータスと判定金額を入力してください');
      return;
    }
    const payload = {
      判定ステータス: status,
      判定金額: amount,
      判定コメント: comment,
      乖離フラグ: true
    };
    const saved = await window.aivicApi.save(4, payload); // 査定員判定結果テーブル
    if (saved) {
      alert('判定を保存しました');
      assessorStatusSelect.value = '';
      assessorAmountInput.value = '';
      judgmentCommentTextarea.value = '';
    }
  });

  // Close modals on overlay click
  [diffModal, validationModal].forEach(modal => {
    if (modal) {
      modal.addEventListener('click', (e) => {
        if (e.target === modal) {
          modal.style.display = 'none';
        }
      });
    }
  });

  // Initial load
  loadDeviationData();
}

function(container, apiUrl, tables) {
  const recordTbody = container.querySelector('#record-tbody');
  const detailPanel = container.querySelector('#detail-panel');
  const detailOverlay = container.querySelector('#detail-overlay');
  const closeDetailBtn = container.querySelector('#close-detail');
  const saveDetailBtn = container.querySelector('#save-detail-btn');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const estimateIdFilter = container.querySelector('[data-testid="estimate-id-filter"]');
  const discrepancyLevelFilter = container.querySelector('[data-testid="discrepancy-level-filter"]');
  const statusFilter = container.querySelector('[data-testid="status-filter"]');

  let allRecords = [];
  let currentDetailRecord = null;

  // 詳細パネル閉じる
  closeDetailBtn.addEventListener('click', () => {
    detailPanel.style.display = 'none';
    detailOverlay.style.display = 'none';
  });

  // 詳細パネル保存
  saveDetailBtn.addEventListener('click', async () => {
    if (!currentDetailRecord) return;
    const improvement = container.querySelector('#detail-improvement').value;
    const status = container.querySelector('#detail-status').value;

    const updated = await window.aivicApi.update(5, currentDetailRecord.id, {
      改善提案: improvement,
      ステータス: status
    });

    if (updated) {
      alert('保存しました');
      detailPanel.style.display = 'none';
      detailOverlay.style.display = 'none';
      loadRecords();
    }
  });

  // 詳細パネル表示
  function showDetail(record) {
    currentDetailRecord = record;
    container.querySelector('#detail-estimate-id').textContent = record.見積書ID || '-';
    container.querySelector('#detail-work-type').textContent = record.工事種別 || '-';
    container.querySelector('#detail-region').textContent = record.地域 || '-';
    container.querySelector('#detail-auto-amount').textContent = (record.自動判定金額 || 0).toLocaleString() + '円';
    container.querySelector('#detail-assessor-amount').textContent = (record.査定員判定金額 || 0).toLocaleString() + '円';
    container.querySelector('#detail-diff-amount').textContent = (record.差異金額 || 0).toLocaleString() + '円';
    container.querySelector('#detail-diff-rate').textContent = record.差異率 || '0';
    container.querySelector('#detail-diff-level').textContent = record.差異レベル || '-';
    container.querySelector('#detail-diff-type').textContent = record.差異タイプ || '-';
    container.querySelector('#detail-auto-reason').textContent = record.自動判定根拠 || '-';
    container.querySelector('#detail-assessor-reason').textContent = record.査定員判定根拠 || '-';
    container.querySelector('#detail-cause-class').textContent = record.差異原因分類 || '-';
    container.querySelector('#detail-improvement').value = record.改善提案 || '';
    container.querySelector('#detail-status').value = record.ステータス || '未確認';

    detailPanel.style.display = 'block';
    detailOverlay.style.display = 'block';
  }

  // 一覧描画
  function renderRecords(records) {
    recordTbody.innerHTML = '';
    if (records.length === 0) {
      recordTbody.innerHTML = '<tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);"><td colspan="8" style="padding: 12px; text-align: center; color: var(--text-muted);">該当するレコードがありません</td></tr>';
      return;
    }
    records.forEach(record => {
      const row = document.createElement('tr');
      row.style.cssText = 'background: var(--bg-main); border-bottom: 1px solid var(--border);';
      row.innerHTML = `
        <td style="padding: 8px; border-right: 1px solid var(--border);">${record.見積書ID || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">${record.自動判定結果 || '-'}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); text-align: right;">${(record.自動判定金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); text-align: right;">${(record.査定員判定金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); text-align: right; font-weight: 600;">${(record.差異金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); text-align: right;">${record.差異率 || '0'}%</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);"><span style="padding: 2px 6px; border-radius: 3px; background: ${record.差異レベル === '重大' ? '#d32f2f' : record.差異レベル === '中程度' ? '#f57c00' : '#388e3c'}; color: #fff; font-size: 11px;">${record.差異レベル || '-'}</span></td>
        <td style="padding: 8px;"><button class="detail-btn" data-id="${record.id}" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 3px; font-size: 11px; cursor: pointer;">詳細</button></td>
      `;
      recordTbody.appendChild(row);
    });

    // 詳細ボタンリスナー
    container.querySelectorAll('.detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const id = e.target.dataset.id;
        const record = allRecords.find(r => r.id === id);
        if (record) showDetail(record);
      });
    });
  }

  // データ読込
  async function loadRecords() {
    const records = await window.aivicApi.list(5);
    allRecords = records || [];
    applyFilters();
  }

  // フィルタ適用
  function applyFilters() {
    const estimateId = estimateIdFilter.value.toLowerCase();
    const discrepancyLevel = discrepancyLevelFilter.value;
    const status = statusFilter.value;

    const filtered = allRecords.filter(r => {
      const matchEstimate = !estimateId || (r.見積書ID || '').toLowerCase().includes(estimateId);
      const matchLevel = !discrepancyLevel || r.差異レベル === discrepancyLevel;
      const matchStatus = !status || r.判定ステータス === status;
      return matchEstimate && matchLevel && matchStatus;
    });

    renderRecords(filtered);
  }

  // 検索ボタン
  searchBtn.addEventListener('click', applyFilters);
  estimateIdFilter.addEventListener('keyup', applyFilters);
  discrepancyLevelFilter.addEventListener('change', applyFilters);
  statusFilter.addEventListener('change', applyFilters);

  // 初期ロード
  loadRecords();
}

function(container, apiUrl, tables) {
  const fileInput = container.querySelector('#file-input');
  const selectFileBtn = container.querySelector('#select-file-btn');
  const clearFilesBtn = container.querySelector('#clear-files-btn');
  const uploadDropZone = container.querySelector('#upload-drop-zone');
  const fileListSection = container.querySelector('#file-list-section');
  const fileList = container.querySelector('#file-list');
  const processedFilesTbody = container.querySelector('#processed-files-tbody');
  const noFilesMessage = container.querySelector('#no-files-message');
  const priceMasterSelect = container.querySelector('#price-master-select');
  const regionSelect = container.querySelector('#region-select');
  const ocrExecuteBtn = container.querySelector('#ocr-execute-btn');
  const autoJudgeBtn = container.querySelector('#auto-judge-btn');
  const nextStepBtn = container.querySelector('#next-step-btn');
  const progressSection = container.querySelector('#progress-section');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const errorMessage = container.querySelector('#error-message');

  let selectedFiles = [];
  let processedFiles = [];

  // ファイル選択ボタンクリック
  selectFileBtn.addEventListener('click', () => {
    fileInput.click();
  });

  // ファイル入力変更
  fileInput.addEventListener('change', (e) => {
    handleFileSelection(Array.from(e.target.files));
  });

  // ドラッグ&ドロップ
  uploadDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadDropZone.style.borderColor = 'var(--primary)';
    uploadDropZone.style.background = 'rgba(74, 85, 104, 0.05)';
  });

  uploadDropZone.addEventListener('dragleave', () => {
    uploadDropZone.style.borderColor = 'var(--border)';
    uploadDropZone.style.background = 'var(--bg-main)';
  });

  uploadDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadDropZone.style.borderColor = 'var(--border)';
    uploadDropZone.style.background = 'var(--bg-main)';
    handleFileSelection(Array.from(e.dataTransfer.files));
  });

  // ファイル選択処理
  function handleFileSelection(files) {
    const validFiles = files.filter(f => {
      const validTypes = ['application/pdf', 'image/png', 'image/jpeg'];
      const validSize = f.size <= 10 * 1024 * 1024;
      return validTypes.includes(f.type) && validSize;
    });

    if (validFiles.length === 0) {
      showError('有効なファイルが選択されていません (PDF, PNG, JPG のみ、最大10MB)');
      return;
    }

    selectedFiles = validFiles;
    renderFileList();
    fileListSection.style.display = 'block';
    clearError();
  }

  // ファイル一覧表示
  function renderFileList() {
    fileList.innerHTML = selectedFiles.map((file, idx) => `
      <div style="
        padding: 10px 12px;
        border-bottom: 1px solid var(--border);
        display: flex;
        justify-content: space-between;
        align-items: center;
        font-size: 13px;
      ">
        <div style="flex: 1;">
          <div style="color: var(--text); font-weight: 500;">${file.name}</div>
          <div style="color: var(--text-muted); font-size: 11px;">
            ${(file.size / 1024).toFixed(1)} KB
          </div>
        </div>
        <button 
          class="remove-file-btn"
          data-index="${idx}"
          style="
            padding: 4px 8px;
            font-size: 12px;
            border: 1px solid var(--border);
            background: transparent;
            color: var(--text);
            cursor: pointer;
            border-radius: 3px;
          "
        >
          削除
        </button>
      </div>
    `).join('');

    container.querySelectorAll('.remove-file-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const idx = parseInt(e.target.dataset.index);
        selectedFiles.splice(idx, 1);
        if (selectedFiles.length === 0) {
          fileListSection.style.display = 'none';
        } else {
          renderFileList();
        }
      });
    });
  }

  // クリアボタン
  clearFilesBtn.addEventListener('click', () => {
    selectedFiles = [];
    fileInput.value = '';
    fileListSection.style.display = 'none';
    clearError();
  });

  // OCR読取実行
  ocrExecuteBtn.addEventListener('click', async () => {
    if (selectedFiles.length === 0) {
      showError('ファイルを選択してください');
      return;
    }

    if (!priceMasterSelect.value) {
      showError('物価本マスタを選択してください');
      return;
    }

    await executeProcessing('ocr');
  });

  // 自動判定実行
  autoJudgeBtn.addEventListener('click', async () => {
    if (selectedFiles.length === 0) {
      showError('ファイルを選択してください');
      return;
    }

    if (!priceMasterSelect.value) {
      showError('物価本マスタを選択してください');
      return;
    }

    await executeProcessing('judge');
  });

  // 処理実行
  async function executeProcessing(type) {
    clearError();
    progressSection.style.display = 'block';
    ocrExecuteBtn.disabled = true;
    autoJudgeBtn.disabled = true;

    try {
      // シミュレーション: プログレスバーを段階的に進める
      for (let i = 0; i <= 100; i += 10) {
        progressBar.style.width = i + '%';
        progressText.textContent = i + '%';
        await new Promise(resolve => setTimeout(resolve, 200));
      }

      // 処理済みファイルに追加
      const now = new Date();
      selectedFiles.forEach(file => {
        processedFiles.push({
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          uploadedAt: now.toLocaleString('ja-JP'),
          status: type === 'ocr' ? 'OCR読取完了' : '自動判定完了'
        });
      });

      renderProcessedFiles();
      selectedFiles = [];
      fileInput.value = '';
      fileListSection.style.display = 'none';
      progressSection.style.display = 'none';

    } catch (err) {
      showError('処理中にエラーが発生しました: ' + err.message);
    } finally {
      ocrExecuteBtn.disabled = false;
      autoJudgeBtn.disabled = false;
    }
  }

  // 処理済みファイル表示
  function renderProcessedFiles() {
    if (processedFiles.length === 0) {
      processedFilesTbody.innerHTML = '';
      noFilesMessage.style.display = 'block';
      return;
    }

    noFilesMessage.style.display = 'none';
    processedFilesTbody.innerHTML = processedFiles.map(file => `
      <tr style="border-bottom: 1px solid var(--border); background: var(--bg-main);">
        <td style="padding: 10px 12px; color: var(--text); font-size: 13px;">${file.name}</td>
        <td style="padding: 10px 12px; text-align: center; color: var(--text-muted); font-size: 12px;">
          ${(file.size / 1024).toFixed(1)} KB
        </td>
        <td style="padding: 10px 12px; text-align: center; color: var(--text-muted); font-size: 12px;">
          ${file.uploadedAt}
        </td>
        <td style="padding: 10px 12px; text-align: center; color: var(--text); font-size: 12px;">
          <span style="
            display: inline-block;
            padding: 4px 8px;
            background: var(--primary);
            color: #fff;
            border-radius: 3px;
            font-size: 11px;
          ">${file.status}</span>
        </td>
        <td style="padding: 10px 12px; text-align: center;">
          <button 
            class="view-detail-btn"
            data-id="${file.id}"
            style="
              padding: 4px 8px;
              font-size: 12px;
              border: 1px solid var(--border);
              background: transparent;
              color: var(--text);
              cursor: pointer;
              border-radius: 3px;
            "
          >
            詳細
          </button>
        </td>
      </tr>
    `).join('');

    container.querySelectorAll('.view-detail-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const fileId = e.target.dataset.id;
        const file = processedFiles.find(f => f.id === fileId);
        if (file) {
          // OCR検証・原本確認画面へ遷移
          window.showScreen('scr-1783330341925');
        }
      });
    });
  }

  // 次へボタン
  nextStepBtn.addEventListener('click', () => {
    if (processedFiles.length === 0) {
      showError('処理済みファイルがありません');
      return;
    }
    window.showScreen('scr-1783330341925');
  });

  // エラー表示
  function showError(msg) {
    errorMessage.textContent = msg;
    errorMessage.style.display = 'block';
  }

  // エラークリア
  function clearError() {
    errorMessage.style.display = 'none';
    errorMessage.textContent = '';
  }

  // 初期表示
  renderProcessedFiles();
}

function(container, apiUrl, tables) {
  let selectedFile = null;
  let ocrResult = null;

  // ファイル選択ボタン
  const fileSelectBtn = container.querySelector('#file-select-btn');
  const fileInput = container.querySelector('#file-input');
  const uploadZone = container.querySelector('#upload-zone');

  fileSelectBtn.addEventListener('click', () => fileInput.click());

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  // ドラッグ&ドロップ
  uploadZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--primary)';
    uploadZone.style.background = 'rgba(74, 85, 104, 0.05)';
  });

  uploadZone.addEventListener('dragleave', () => {
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
  });

  uploadZone.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
    if (e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  });

  function handleFileSelect(file) {
    selectedFile = file;
    const fileInfo = container.querySelector('#file-info');
    const fileName = container.querySelector('#file-name');
    const fileSize = container.querySelector('#file-size');

    fileName.textContent = file.name;
    fileSize.textContent = (file.size / 1024).toFixed(1) + ' KB';
    fileInfo.style.display = 'block';

    // 手動修正セクション表示
    container.querySelector('#manual-edit-section').style.display = 'block';
  }

  // OCR読取開始
  const ocrStartBtn = container.querySelector('#ocr-start-btn');
  ocrStartBtn.addEventListener('click', async () => {
    if (!selectedFile) {
      showError('ファイルを選択してください');
      return;
    }

    const lang = container.querySelector('#ocr-lang').value;
    const structure = container.querySelector('#ocr-structure').checked;

    // 進捗表示
    container.querySelector('#progress-section').style.display = 'block';
    ocrStartBtn.disabled = true;

    // シミュレーション: 進捗バー
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 30;
      if (progress > 100) progress = 100;
      updateProgress(progress);
      if (progress >= 100) clearInterval(progressInterval);
    }, 300);

    // 実際のOCR処理（API呼び出しまたはシミュレーション）
    setTimeout(() => {
      clearInterval(progressInterval);
      updateProgress(100);

      // ダミーOCR結果
      ocrResult = {
        rawText: `見積書\n\n発行日: 2024年1月15日\n\n【発注者】\n株式会社ABC建設\n東京都渋谷区\n\n【受注者】\n株式会社XYZ工務店\n神奈川県横浜市\n\n【工事内容】\n外壁塗装工事\n\n【見積金額】\n¥850,000\n\n【内訳】\n労務費: ¥350,000\n材料費: ¥400,000\n経費: ¥100,000`,
        structured: {
          issueDate: '2024-01-15',
          company: '株式会社XYZ工務店',
          amount: 850000,
          laborCost: 350000,
          materialCost: 400000,
          expense: 100000,
          workType: '外壁塗装工事'
        },
        confidence: {
          text: 92,
          structure: 88
        },
        items: [
          { name: '見積日', value: '2024年1月15日', confidence: 95 },
          { name: '企業名', value: '株式会社XYZ工務店', confidence: 90 },
          { name: '見積金額', value: '¥850,000', confidence: 94 },
          { name: '労務費', value: '¥350,000', confidence: 88 },
          { name: '材料費', value: '¥400,000', confidence: 91 },
          { name: '経費', value: '¥100,000', confidence: 85 }
        ]
      };

      displayOCRResult();
      container.querySelector('#next-step-btn').style.display = 'block';
      ocrStartBtn.disabled = false;
      showSuccess('OCR読取が完了しました');
    }, 2000);
  });

  function updateProgress(percent) {
    container.querySelector('#progress-bar').style.width = percent + '%';
    container.querySelector('#progress-text').textContent = Math.round(percent) + '%';
  }

  function displayOCRResult() {
    if (!ocrResult) return;

    // 抽出テキスト
    container.querySelector('#extracted-text').textContent = ocrResult.rawText;

    // 構造化データ
    const structuredTbody = container.querySelector('#structured-tbody');
    structuredTbody.innerHTML = '';
    for (const [key, value] of Object.entries(ocrResult.structured)) {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 4px; color: var(--text-muted); width: 40%;">${key}</td>
        <td style="padding: 4px; color: var(--text);">${value}</td>
      `;
      structuredTbody.appendChild(row);
    }

    // 信頼度スコア
    container.querySelector('#score-text').textContent = ocrResult.confidence.text;
    container.querySelector('#score-structure').textContent = ocrResult.confidence.structure;

    // 項目別抽出結果
    const extractionTbody = container.querySelector('#extraction-tbody');
    extractionTbody.innerHTML = '';
    ocrResult.items.forEach(item => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      const confidenceColor = item.confidence >= 90 ? '#388e3c' : item.confidence >= 80 ? '#f57c00' : '#d32f2f';
      row.innerHTML = `
        <td style="padding: 6px; color: var(--text);">${item.name}</td>
        <td style="padding: 6px; color: var(--text);">${item.value}</td>
        <td style="padding: 6px; text-align: center; color: ${confidenceColor}; font-weight: 600;">${item.confidence}%</td>
      `;
      extractionTbody.appendChild(row);
    });
  }

  // 手動修正保存
  const manualSaveBtn = container.querySelector('#manual-save-btn');
  manualSaveBtn.addEventListener('click', () => {
    const company = container.querySelector('#manual-company').value;
    const amount = container.querySelector('#manual-amount').value;
    const date = container.querySelector('#manual-date').value;

    if (ocrResult) {
      if (company) ocrResult.structured.company = company;
      if (amount) ocrResult.structured.amount = parseInt(amount);
      if (date) ocrResult.structured.issueDate = date;
    }

    showSuccess('修正内容を保存しました');
  });

  // 次へボタン
  const nextStepBtn = container.querySelector('#next-step-btn');
  nextStepBtn.addEventListener('click', () => {
    if (ocrResult) {
      // 次の画面へ遷移（OCR検証・原本確認画面）
      window.showScreen('scr-1783330341925');
    }
  });

  // キャンセルボタン
  const cancelBtn = container.querySelector('#cancel-btn');
  cancelBtn.addEventListener('click', () => {
    // 見積書登録・OCR読取画面へ戻る
    window.showScreen('scr-1783330328733');
  });

  // メッセージ表示関数
  function showError(message) {
    const banner = container.querySelector('#error-banner');
    container.querySelector('#error-text').textContent = message;
    banner.style.display = 'block';
    setTimeout(() => {
      banner.style.display = 'none';
    }, 4000);
  }

  function showSuccess(message) {
    const banner = container.querySelector('#success-banner');
    container.querySelector('#success-text').textContent = message;
    banner.style.display = 'block';
    setTimeout(() => {
      banner.style.display = 'none';
    }, 3000);
  }
}

function(container, apiUrl, tables) {
  const estimateList = tables[0]?.records || [];
  const pastProjectsData = tables[1]?.records || [];
  const priceMasterData = tables[2]?.records || [];
  const deviationAnalysisData = tables[3]?.records || [];
  const autoJudgmentData = tables[4]?.records || [];

  let selectedEstimateId = null;
  let currentDeviationData = [];

  // ========== 見積書一覧の初期化 ==========
  async function loadEstimates() {
    try {
      const estimates = await window.aivicApi.list(0);
      if (!estimates) return;

      const tbody = container.querySelector('#estimate-tbody');
      tbody.innerHTML = '';

      estimates.forEach((est, idx) => {
        const tr = document.createElement('tr');
        tr.dataset.id = est.id;
        tr.style.cssText = `
          border-bottom: 1px solid var(--border);
          cursor: pointer;
          background: ${idx % 2 === 0 ? 'var(--bg-card)' : 'var(--bg-main)'};
        `;
        tr.innerHTML = `<td style="padding: 8px; color: var(--text);">${est.id || 'N/A'}</td>`;
        tr.addEventListener('click', () => selectEstimate(est));
        tbody.appendChild(tr);
      });
    } catch (e) {
      console.error('見積書一覧読込エラー:', e);
    }
  }

  // ========== 見積書選択時の処理 ==========
  function selectEstimate(estimate) {
    selectedEstimateId = estimate.id;

    // OCR読取結果を表示
    const ocrPanel = container.querySelector('#ocr-result-panel');
    ocrPanel.innerHTML = `
      <div style="margin-bottom: 8px;">
        <div style="color: var(--text-muted); font-size: 10px;">見積書ID</div>
        <div style="color: var(--text); font-weight: 600;">${estimate.id}</div>
      </div>
      <div style="margin-bottom: 8px;">
        <div style="color: var(--text-muted); font-size: 10px;">工事種別</div>
        <div style="color: var(--text); font-weight: 600;">${estimate.workType || '—'}</div>
      </div>
      <div style="margin-bottom: 8px;">
        <div style="color: var(--text-muted); font-size: 10px;">見積金額</div>
        <div style="color: var(--text); font-weight: 600;">¥${(estimate.estimatedAmount || 0).toLocaleString()}</div>
      </div>
      <div style="margin-bottom: 8px;">
        <div style="color: var(--text-muted); font-size: 10px;">OCR読取日時</div>
        <div style="color: var(--text); font-weight: 600;">${estimate.ocrDate || '—'}</div>
      </div>
    `;

    // 過去案件データを表示
    loadPastProjects(estimate.workType);

    // 物価本データを表示
    loadPriceMaster(estimate.workType);
  }

  // ========== 過去案件データ読込 ==========
  function loadPastProjects(workType) {
    const tbody = container.querySelector('#past-projects-tbody');
    tbody.innerHTML = '';

    const filtered = pastProjectsData.filter(p => !workType || p.workType === workType);

    if (filtered.length === 0) {
      tbody.innerHTML = `<tr><td colspan="2" style="padding: 8px; color: var(--text-muted); text-align: center;">該当データなし</td></tr>`;
      return;
    }

    filtered.slice(0, 5).forEach((proj, idx) => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.innerHTML = `
        <td style="padding: 4px; color: var(--text); font-size: 10px;">${proj.projectId || 'N/A'}</td>
        <td style="padding: 4px; color: var(--text-muted); font-size: 10px; text-align: right;">¥${(proj.amount || 0).toLocaleString()}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  // ========== 物価本データ読込 ==========
  function loadPriceMaster(workType) {
    const tbody = container.querySelector('#price-master-tbody');
    tbody.innerHTML = '';

    const filtered = priceMasterData.filter(p => !workType || p.itemName.includes(workType));

    if (filtered.length === 0) {
      tbody.innerHTML = `<tr><td colspan="2" style="padding: 8px; color: var(--text-muted); text-align: center;">該当データなし</td></tr>`;
      return;
    }

    filtered.slice(0, 5).forEach((item, idx) => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.innerHTML = `
        <td style="padding: 4px; color: var(--text); font-size: 10px;">${item.itemName || 'N/A'}</td>
        <td style="padding: 4px; color: var(--text-muted); font-size: 10px; text-align: right;">¥${(item.standardPrice || 0).toLocaleString()}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  // ========== タブ切り替え ==========
  container.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const tabName = e.target.dataset.tab;

      container.querySelectorAll('.tab-btn').forEach(b => {
        b.style.borderBottomColor = 'transparent';
        b.style.color = 'var(--text-muted)';
        b.style.fontWeight = '400';
      });
      e.target.style.borderBottomColor = 'var(--primary)';
      e.target.style.color = 'var(--text)';
      e.target.style.fontWeight = '600';

      container.querySelector('#past-projects-panel').style.display = tabName === 'past-projects' ? 'block' : 'none';
      container.querySelector('#price-master-panel').style.display = tabName === 'price-master' ? 'block' : 'none';
    });
  });

  // ========== 照合実行 ==========
  container.querySelector('[data-testid="execute-collation-button"]').addEventListener('click', async () => {
    if (!selectedEstimateId) {
      alert('見積書を選択してください');
      return;
    }

    // 乖離分析結果を表示
    const deviationTbody = container.querySelector('#deviation-tbody');
    deviationTbody.innerHTML = '';

    currentDeviationData = deviationAnalysisData.filter(d => d.estimateId === selectedEstimateId);

    if (currentDeviationData.length === 0) {
      deviationTbody.innerHTML = `<tr><td colspan="3" style="padding: 8px; color: var(--text-muted); text-align: center;">乖離データなし</td></tr>`;
    } else {
      currentDeviationData.forEach(dev => {
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid var(--border)';
        const statusColor = dev.deviationRate > 20 ? '#d32f2f' : dev.deviationRate > 10 ? '#f57c00' : '#388e3c';
        tr.innerHTML = `
          <td style="padding: 6px; color: var(--text); font-size: 11px;">${dev.itemName || 'N/A'}</td>
          <td style="padding: 6px; text-align: right; color: var(--text); font-size: 11px;">${dev.deviationRate || 0}%</td>
          <td style="padding: 6px; text-align: right; font-size: 11px; color: ${statusColor}; font-weight: 600;">
            ${dev.deviationRate > 20 ? '要修正' : dev.deviationRate > 10 ? '要確認' : '正常'}
          </td>
        `;
        deviationTbody.appendChild(tr);
      });
    }

    // 自動判定結果を表示
    const autoJudgment = autoJudgmentData.find(a => a.estimateId === selectedEstimateId);
    if (autoJudgment) {
      container.querySelector('#judgment-status').textContent = autoJudgment.judgmentStatus || '—';
      container.querySelector('#judgment-score').textContent = (autoJudgment.judgmentScore || 0) + ' / 100';
      container.querySelector('#market-comparison-rate').textContent = (autoJudgment.marketComparisonRate || 0) + '%';
      container.querySelector('#reference-count').textContent = autoJudgment.pastProjectReferenceCount || 0;
      container.querySelector('#judgment-reason').textContent = autoJudgment.judgmentReason || '—';
    }
  });

  // ========== 検索ボタン ==========
  container.querySelector('[data-testid="search-estimate-button"]').addEventListener('click', async () => {
    const estimateId = container.querySelector('[data-testid="estimate-id-input"]').value;
    const workType = container.querySelector('[data-testid="work-type-select"]').value;

    const tbody = container.querySelector('#estimate-tbody');
    tbody.innerHTML = '';

    let filtered = estimateList;
    if (estimateId) filtered = filtered.filter(e => e.id.includes(estimateId));
    if (workType) filtered = filtered.filter(e => e.workType === workType);

    if (filtered.length === 0) {
      tbody.innerHTML = `<tr><td style="padding: 8px; color: var(--text-muted); text-align: center;">該当データなし</td></tr>`;
      return;
    }

    filtered.forEach((est, idx) => {
      const tr = document.createElement('tr');
      tr.dataset.id = est.id;
      tr.style.cssText = `
        border-bottom: 1px solid var(--border);
        cursor: pointer;
        background: ${idx % 2 === 0 ? 'var(--bg-card)' : 'var(--bg-main)'};
      `;
      tr.innerHTML = `<td style="padding: 8px; color: var(--text);">${est.id}</td>`;
      tr.addEventListener('click', () => selectEstimate(est));
      tbody.appendChild(tr);
    });
  });

  // ========== CSVエクスポート ==========
  container.querySelector('[data-testid="export-csv-button"]').addEventListener('click', () => {
    if (currentDeviationData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['項目名', '見積値', '参照値', '乖離率', '乖離額', '判定'];
    const rows = currentDeviationData.map(d => [
      d.itemName,
      d.estimatedValue,
      d.referenceValue,
      d.deviationRate + '%',
      d.deviationAmount,
      d.deviationJudgment
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(c => `"${c}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `deviation-analysis-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ========== 戻るボタン ==========
  container.querySelector('[data-testid="back-button"]').addEventListener('click', () => {
    window.showScreen('scr-1783330354980');
  });

  // ========== モーダル閉じる ==========
  container.querySelector('[data-testid="close-graph-modal"]').addEventListener('click', () => {
    container.querySelector('#graph-modal').style.display = 'none';
  });

  // ========== 初期化 ==========
  loadEstimates();
}

function(container, apiUrl, tables) {
  const datasetTable = tables[0];
  const datasetTbody = container.querySelector('#dataset-tbody');
  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabPanels = [
    container.querySelector('#tab-datasets-panel'),
    container.querySelector('#tab-preprocessing-panel'),
    container.querySelector('#tab-training-panel')
  ];

  // Tab switching
  tabButtons.forEach((btn, idx) => {
    btn.addEventListener('click', () => {
      tabButtons.forEach(b => b.style.borderBottomColor = 'transparent');
      tabButtons.forEach(b => b.style.color = 'var(--text-muted)');
      tabPanels.forEach(p => p.style.display = 'none');

      btn.style.borderBottomColor = 'var(--primary)';
      btn.style.color = 'var(--text)';
      tabPanels[idx].style.display = 'block';
    });
  });

  // Load datasets
  async function loadDatasets() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    let totalRecords = 0;
    let totalQuality = 0;
    const datasetMap = {};

    rows.forEach(row => {
      const dsName = row['データセット名'] || 'Unknown';
      if (!datasetMap[dsName]) {
        datasetMap[dsName] = { count: 0, quality: 0, updated: row['最終更新日時'] || '', id: row.id };
      }
      datasetMap[dsName].count += 1;
      datasetMap[dsName].quality = row['データ品質スコア'] || 0;
      totalRecords += 1;
    });

    const datasets = Object.entries(datasetMap).map(([name, data]) => ({
      name,
      ...data
    }));

    totalQuality = datasets.length > 0 ? Math.round(datasets.reduce((s, d) => s + d.quality, 0) / datasets.length) : 0;

    container.querySelector('[data-testid="dataset-count"]').textContent = datasets.length;
    container.querySelector('[data-testid="total-records"]').textContent = totalRecords;
    container.querySelector('[data-testid="avg-quality"]').textContent = totalQuality + '%';
    container.querySelector('[data-testid="last-update"]').textContent = datasets[0]?.updated?.substring(0, 10) || '未更新';

    datasetTbody.innerHTML = datasets.map(ds => `
      <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; text-align: center;">
          <input type="checkbox" class="dataset-checkbox" data-id="${ds.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 8px;">${ds.name}</td>
        <td style="padding: 8px; text-align: center;">${ds.count}</td>
        <td style="padding: 8px; text-align: center;"><span style="background: var(--primary); color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${ds.quality}%</span></td>
        <td style="padding: 8px; font-size: 11px; color: var(--text-muted);">${ds.updated?.substring(0, 10) || '-'}</td>
        <td style="padding: 8px; text-align: center;">
          <button class="delete-btn" data-id="${ds.id}" style="padding: 4px 8px; background: transparent; border: 1px solid var(--border); color: var(--text); font-size: 11px; border-radius: 3px; cursor: pointer;">削除</button>
        </td>
      </tr>
    `).join('');

    // Delete handlers
    container.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', async (e) => {
        const id = e.target.dataset.id;
        if (confirm('このデータセットを削除しますか？')) {
          await window.aivicApi.delete(0, id);
          loadDatasets();
        }
      });
    });
  }

  // CSV Export
  container.querySelector('[data-testid="export-csv-btn"]').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) return;

    const headers = Object.keys(rows[0]);
    const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(r => 
      headers.map(h => {
        const val = r[h] || '';
        return typeof val === 'string' && val.includes(',') ? `"${val}"` : val;
      }).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'datasets.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  // Upload Modal
  const uploadModal = container.querySelector('#upload-modal');
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#file-input');
  const previewContainer = container.querySelector('#preview-container');
  const previewHeader = container.querySelector('#preview-header');
  const previewBody = container.querySelector('#preview-body');
  const uploadConfirmBtn = container.querySelector('[data-testid="upload-confirm-btn"]');
  let uploadedData = [];

  container.querySelector('[data-testid="upload-btn"]').addEventListener('click', () => {
    uploadModal.style.display = 'flex';
  });

  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--primary)';
  });

  dropZone.addEventListener('dragleave', () => {
    dropZone.style.borderColor = 'var(--border)';
  });

  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.style.borderColor = 'var(--border)';
    const files = e.dataTransfer.files;
    if (files.length > 0) handleFile(files[0]);
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) handleFile(e.target.files[0]);
  });

  function handleFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target.result;
      const lines = text.trim().split('\n');
      const headers = lines[0].split(',');
      uploadedData = lines.slice(1, 6).map(line => {
        const vals = line.split(',');
        return headers.reduce((obj, h, i) => ({ ...obj, [h]: vals[i] || '' }), {});
      });

      previewHeader.innerHTML = headers.map(h => `<th style="padding: 6px; text-align: left; border-right: 1px solid var(--border);">${h}</th>`).join('');
      previewBody.innerHTML = uploadedData.map(row => `
        <tr style="border-bottom: 1px solid var(--border);">
          ${headers.map(h => `<td style="padding: 6px; border-right: 1px solid var(--border);">${row[h]}</td>`).join('')}
        </tr>
      `).join('');

      previewContainer.style.display = 'block';
      uploadConfirmBtn.style.display = 'block';
    };
    reader.readAsText(file);
  }

  uploadConfirmBtn.addEventListener('click', async () => {
    for (const row of uploadedData) {
      await window.aivicApi.save(0, row);
    }
    uploadModal.style.display = 'none';
    loadDatasets();
  });

  // Training
  container.querySelector('[data-testid="train-btn"]').addEventListener('click', () => {
    const status = container.querySelector('#training-status');
    const bar = container.querySelector('#progress-bar');
    const msg = container.querySelector('#training-message');
    status.style.display = 'block';
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        msg.textContent = '✓ 学習完了';
      }
      bar.style.width = progress + '%';
      msg.textContent = `学習中... ${Math.round(progress)}%`;
    }, 500);
  });

  container.querySelector('[data-testid="refresh-btn"]').addEventListener('click', loadDatasets);

  loadDatasets();
}

function(container, apiUrl, tables) {
  // ========== 状態管理 ==========
  let currentFile = null;
  let extractedData = {};
  let processingState = 'idle'; // idle | processing | completed | error

  // ========== DOM 要素キャッシュ ==========
  const uploadZone = container.querySelector('#upload-zone');
  const fileInput = container.querySelector('#file-input');
  const fileInfo = container.querySelector('#file-info');
  const fileName = container.querySelector('#file-name');
  const fileSize = container.querySelector('#file-size');
  const languageSelect = container.querySelector('[data-testid="language-select"]');
  const modeSelect = container.querySelector('[data-testid="mode-select"]');
  const executeBtn = container.querySelector('#execute-btn');
  const progressPanel = container.querySelector('#progress-panel');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const historyList = container.querySelector('#history-list');
  const imagePreview = container.querySelector('#image-preview');
  const extractionTbody = container.querySelector('#extraction-tbody');
  const saveBtn = container.querySelector('#save-btn');
  const nextBtn = container.querySelector('#next-btn');
  const confirmOverlay = container.querySelector('#confirm-overlay');
  const confirmMessage = container.querySelector('#confirm-message');
  const confirmCancel = container.querySelector('#confirm-cancel');
  const confirmOk = container.querySelector('#confirm-ok');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');

  // ========== ユーティリティ ==========
  function showError(msg) {
    errorText.textContent = msg;
    errorMessage.style.display = 'block';
    setTimeout(() => { errorMessage.style.display = 'none'; }, 5000);
  }

  function showConfirm(msg, callback) {
    confirmMessage.textContent = msg;
    confirmOverlay.style.display = 'flex';
    confirmOk.onclick = () => {
      confirmOverlay.style.display = 'none';
      callback(true);
    };
    confirmCancel.onclick = () => {
      confirmOverlay.style.display = 'none';
      callback(false);
    };
  }

  function formatFileSize(bytes) {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
  }

  function addToHistory(status, filename) {
    const now = new Date().toLocaleTimeString('ja-JP');
    const historyItem = document.createElement('div');
    historyItem.style.cssText = 'padding: 6px 0; border-bottom: 1px solid var(--border); font-size: 10px;';
    const statusColor = status === 'success' ? '#4caf50' : status === 'error' ? '#d32f2f' : '#ff9800';
    historyItem.innerHTML = `
      <div style="color: ${statusColor}; font-weight: 600;">${status === 'success' ? '✓' : status === 'error' ? '✗' : '⊙'} ${status.toUpperCase()}</div>
      <div style="color: var(--text-muted); margin-top: 2px;">${filename}</div>
      <div style="color: var(--text-muted); font-size: 9px;">${now}</div>
    `;
    if (historyList.firstChild && historyList.firstChild.textContent.includes('履歴なし')) {
      historyList.innerHTML = '';
    }
    historyList.insertBefore(historyItem, historyList.firstChild);
  }

  // ========== ファイルアップロード処理 ==========
  uploadZone.addEventListener('click', () => fileInput.click());
  uploadZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--primary)';
    uploadZone.style.background = 'rgba(74, 85, 104, 0.05)';
  });
  uploadZone.addEventListener('dragleave', () => {
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
  });
  uploadZone.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadZone.style.borderColor = 'var(--border)';
    uploadZone.style.background = 'var(--bg-main)';
    if (e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  function handleFileSelect(file) {
    // ファイル検証
    const validTypes = ['image/jpeg', 'image/png', 'application/pdf'];
    if (!validTypes.includes(file.type)) {
      showError('JPG / PNG / PDF ファイルのみ対応しています');
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      showError('ファイルサイズは 10MB 以下にしてください');
      return;
    }

    currentFile = file;
    fileName.textContent = file.name;
    fileSize.textContent = formatFileSize(file.size);
    fileInfo.style.display = 'block';
    executeBtn.disabled = false;

    // 画像プレビュー
    if (file.type !== 'application/pdf') {
      const reader = new FileReader();
      reader.onload = (e) => {
        imagePreview.innerHTML = `<img src="${e.target.result}" style="max-width: 100%; max-height: 100%; object-fit: contain;" />`;
      };
      reader.readAsDataURL(file);
    } else {
      imagePreview.innerHTML = '<div style="text-align: center; color: var(--text-muted);">📄 PDF ファイル</div>';
    }

    // 結果クリア
    extractedData = {};
    extractionTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="2" style="padding: 24px; text-align: center; color: var(--text-muted);">OCR 読取を実行してください</td></tr>';
    saveBtn.disabled = true;
    nextBtn.disabled = true;
  }

  // ========== OCR 実行 ==========
  executeBtn.addEventListener('click', async () => {
    if (!currentFile) {
      showError('ファイルを選択してください');
      return;
    }

    const lang = languageSelect.value || 'ja';
    const mode = modeSelect.value || 'standard';

    if (!lang || !mode) {
      showError('言語と処理モードを選択してください');
      return;
    }

    processingState = 'processing';
    executeBtn.disabled = true;
    progressPanel.style.display = 'block';
    progressBar.style.width = '0%';
    progressText.textContent = 'ファイルを準備中...';

    try {
      // シミュレーション: 実際には API に送信
      await simulateOCRProcessing(lang, mode);

      processingState = 'completed';
      progressText.textContent = '読取完了';
      progressBar.style.width = '100%';
      addToHistory('success', currentFile.name);

      // 結果を表示
      renderExtractionResults();
      saveBtn.disabled = false;
      nextBtn.disabled = false;

      setTimeout(() => {
        progressPanel.style.display = 'none';
        executeBtn.disabled = false;
      }, 1500);

    } catch (err) {
      processingState = 'error';
      showError('OCR 読取に失敗しました: ' + err.message);
      addToHistory('error', currentFile.name);
      progressPanel.style.display = 'none';
      executeBtn.disabled = false;
    }
  });

  async function simulateOCRProcessing(lang, mode) {
    return new Promise((resolve) => {
      let progress = 0;
      const interval = setInterval(() => {
        progress += Math.random() * 30;
        if (progress >= 100) {
          progress = 100;
          clearInterval(interval);

          // ダミー抽出データ
          extractedData = {
            '業者名': { value: '株式会社 ABC 建設', confidence: 0.95 },
            '住所': { value: '東京都渋谷区 1-2-3', confidence: 0.88 },
            '電話番号': { value: '03-1234-5678', confidence: 0.92 },
            '工事内容': { value: '外壁塗装工事一式', confidence: 0.87 },
            '施工日程': { value: '2024年4月1日～2024年4月30日', confidence: 0.85 },
            '見積金額': { value: '1,500,000', confidence: 0.93 },
            '労務費': { value: '600,000', confidence: 0.90 },
            '材料費': { value: '700,000', confidence: 0.89 },
            '経費': { value: '200,000', confidence: 0.86 }
          };

          resolve();
        } else {
          progressBar.style.width = progress + '%';
          const steps = ['ファイルを準備中...', 'OCR エンジン起動...', 'テキスト抽出中...', 'データ検証中...', '完了間近...'];
          progressText.textContent = steps[Math.floor(progress / 20)] || '処理中...';
        }
      }, 300);
    });
  }

  function renderExtractionResults() {
    extractionTbody.innerHTML = '';
    Object.entries(extractedData).forEach(([key, data]) => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      row.innerHTML = `
        <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-weight: 500; width: 120px;">${key}</td>
        <td style="padding: 8px;">
          <input type="text" value="${data.value}" data-field="${key}" class="extraction-input" style="width: 100%; padding: 4px 6px; border: 1px solid var(--border); border-radius: 3px; background: var(--bg-card); color: var(--text); font-size: 11px;" data-testid="extraction-${key}" />
          <div style="font-size: 9px; color: var(--text-muted); margin-top: 2px;">信頼度: ${(data.confidence * 100).toFixed(0)}%</div>
        </td>
      `;
      extractionTbody.appendChild(row);
    });
  }

  // ========== 結果保存 ==========
  saveBtn.addEventListener('click', async () => {
    const updatedData = {};
    container.querySelectorAll('.extraction-input').forEach(input => {
      updatedData[input.dataset.field] = input.value;
    });

    try {
      // API 経由で保存（テーブルインデックス 0 を想定）
      const saved = await window.aivicApi.save(0, {
        extracted_data: JSON.stringify(updatedData),
        file_name: currentFile.name,
        file_size: currentFile.size,
        processing_status: 'completed',
        created_at: new Date().toISOString()
      });

      if (saved) {
        showConfirm('OCR 読取結果を保存しました。次のステップに進みますか？', (ok) => {
          if (ok) {
            window.showScreen('scr-1783330341925'); // OCR検証・原本確認画面へ
          }
        });
      }
    } catch (err) {
      showError('保存に失敗しました');
    }
  });

  // ========== 次へボタン ==========
  nextBtn.addEventListener('click', () => {
    if (Object.keys(extractedData).length === 0) {
      showError('OCR 読取を実行してください');
      return;
    }
    window.showScreen('scr-1783330341925'); // OCR検証・原本確認画面へ
  });

  // ========== Esc キーでダイアログ閉じる ==========
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && confirmOverlay.style.display === 'flex') {
      confirmOverlay.style.display = 'none';
    }
  });

  // ========== 初期化完了 ==========
  console.log('OCR読取実行・結果取得 画面 初期化完了');
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const TABLE_INDEX = 0; // OCR読取結果用テーブル

  // DOM要素の取得
  const imageContainer = container.querySelector('#image-container');
  const ocrTextDisplay = container.querySelector('#ocr-text-display');
  const estimateNumberInput = container.querySelector('#estimate-number');
  const issueDateInput = container.querySelector('#issue-date');
  const clientNameInput = container.querySelector('#client-name');
  const contractorNameInput = container.querySelector('#contractor-name');
  const workContentInput = container.querySelector('#work-content');
  const workLocationInput = container.querySelector('#work-location');
  const totalAmountInput = container.querySelector('#total-amount');
  const taxRateInput = container.querySelector('#tax-rate');
  const totalWithTaxInput = container.querySelector('#total-with-tax');
  const detailLinesTbody = container.querySelector('#detail-lines-tbody');
  const btnCancel = container.querySelector('#btn-cancel');
  const btnVerify = container.querySelector('#btn-verify');
  const btnSave = container.querySelector('#btn-save');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const successMessage = container.querySelector('#success-message');
  const successText = container.querySelector('#success-text');

  // 初期データの取得
  let currentEstimate = null;
  let currentOcrResult = null;

  // メッセージ表示関数
  function showError(message) {
    errorText.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 4000);
  }

  function showSuccess(message) {
    successText.textContent = message;
    successMessage.style.display = 'block';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // 税込合計の自動計算
  function calculateTotalWithTax() {
    const total = parseFloat(totalAmountInput.value) || 0;
    const taxRate = parseFloat(taxRateInput.value) || 0;
    const taxAmount = total * (taxRate / 100);
    const totalWithTax = total + taxAmount;
    totalWithTaxInput.value = totalWithTax.toFixed(0);
  }

  // 金額入力時のイベントリスナー
  totalAmountInput.addEventListener('change', calculateTotalWithTax);
  taxRateInput.addEventListener('change', calculateTotalWithTax);

  // 明細行テーブルの描画
  function renderDetailLines(lines) {
    if (!lines || lines.length === 0) {
      detailLinesTbody.innerHTML = '<tr><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted); border-bottom: 1px solid var(--border);">明細行がありません</td></tr>';
      return;
    }

    detailLinesTbody.innerHTML = lines.map((line, idx) => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 8px; color: var(--text);">${line.itemName || ''}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${line.quantity || ''}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${line.unit || ''}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${(line.unitPrice || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${(line.amount || 0).toLocaleString()}</td>
      </tr>
    `).join('');
  }

  // 見積書画像の表示
  function displayEstimateImage(imageUrl) {
    if (imageUrl) {
      imageContainer.innerHTML = `<img src="${imageUrl}" style="max-width: 100%; max-height: 100%; object-fit: contain;" alt="見積書画像" />`;
    } else {
      imageContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 13px;"><div style="margin-bottom: 8px;">📄</div><div>画像が利用できません</div></div>';
    }
  }

  // OCR読取テキストの表示
  function displayOcrText(text) {
    if (text) {
      ocrTextDisplay.textContent = text;
    } else {
      ocrTextDisplay.textContent = '読取テキストがありません';
    }
  }

  // フォームへのデータ入力
  function populateForm(data) {
    if (!data) return;

    estimateNumberInput.value = data.estimateNumber || '';
    issueDateInput.value = data.issueDate || '';
    clientNameInput.value = data.clientName || '';
    contractorNameInput.value = data.contractorName || '';
    workContentInput.value = data.workContent || '';
    workLocationInput.value = data.workLocation || '';
    totalAmountInput.value = data.totalAmount || '';
    taxRateInput.value = data.taxRate || '10';

    calculateTotalWithTax();
    renderDetailLines(data.detailLines || []);
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // URLパラメータから見積書IDを取得（あれば）
      const params = new URLSearchParams(window.location.search);
      const estimateId = params.get('id');

      if (estimateId && window.aivicApi) {
        // APIから見積書データを取得
        const records = await window.aivicApi.list(TABLE_INDEX);
        currentEstimate = records.find(r => r.id === estimateId);

        if (currentEstimate) {
          displayEstimateImage(currentEstimate.imageUrl);
          displayOcrText(currentEstimate.ocrText);
          populateForm(currentEstimate);
        } else {
          showError('見積書データが見つかりません');
        }
      } else if (tables && tables[TABLE_INDEX] && tables[TABLE_INDEX].records && tables[TABLE_INDEX].records.length > 0) {
        // テーブルの初期データから最初のレコードを使用
        currentEstimate = tables[TABLE_INDEX].records[0];
        displayEstimateImage(currentEstimate.imageUrl);
        displayOcrText(currentEstimate.ocrText);
        populateForm(currentEstimate);
      } else {
        // ダミーデータを表示
        displayEstimateImage(null);
        displayOcrText('OCR読取テキストがここに表示されます。');
        renderDetailLines([]);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // 保存処理
  async function saveData() {
    try {
      const formData = {
        estimateNumber: estimateNumberInput.value,
        issueDate: issueDateInput.value,
        clientName: clientNameInput.value,
        contractorName: contractorNameInput.value,
        workContent: workContentInput.value,
        workLocation: workLocationInput.value,
        totalAmount: parseFloat(totalAmountInput.value) || 0,
        taxRate: parseFloat(taxRateInput.value) || 10,
        totalWithTax: parseFloat(totalWithTaxInput.value) || 0,
      };

      if (currentEstimate && currentEstimate.id && window.aivicApi) {
        // 既存レコードの更新
        await window.aivicApi.update(TABLE_INDEX, currentEstimate.id, formData);
        showSuccess('見積書データを保存しました');
      } else if (window.aivicApi) {
        // 新規レコードの保存
        const saved = await window.aivicApi.save(TABLE_INDEX, formData);
        if (saved) {
          currentEstimate = saved;
          showSuccess('見積書データを保存しました');
        }
      } else {
        showError('保存機能が利用できません');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存に失敗しました');
    }
  }

  // キャンセル処理
  function cancel() {
    if (confirm('変更内容を破棄してもよろしいですか？')) {
      window.showScreen('scr-1783330341925'); // OCR検証・原本確認画面へ遷移
    }
  }

  // 検証・確認へ処理
  function verifyAndProceed() {
    if (!estimateNumberInput.value.trim()) {
      showError('見積書番号を入力してください');
      return;
    }
    if (!issueDateInput.value) {
      showError('発行日を入力してください');
      return;
    }
    if (!totalAmountInput.value) {
      showError('合計金額を入力してください');
      return;
    }

    // 先に保存してから遷移
    saveData().then(() => {
      // 乖離分析・相場判定画面へ遷移
      window.showScreen('scr-1783330354980');
    }).catch(() => {
      showError('保存に失敗しました。再度お試しください。');
    });
  }

  // イベントリスナーの登録
  btnCancel.addEventListener('click', cancel);
  btnSave.addEventListener('click', saveData);
  btnVerify.addEventListener('click', verifyAndProceed);

  // 初期データの読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  const retrainingBtn = container.querySelector('[data-testid="start-retraining-btn"]');
  const validationBtn = container.querySelector('[data-testid="start-validation-btn"]');
  const backBtn = container.querySelector('[data-testid="back-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');

  // 再学習実行
  retrainingBtn.addEventListener('click', async () => {
    const dataset = container.querySelector('[data-testid="training-dataset-select"]').value;
    const table = container.querySelector('[data-testid="training-table-select"]').value;
    const startDate = container.querySelector('[data-testid="training-start-date"]').value;
    const endDate = container.querySelector('[data-testid="training-end-date"]').value;
    const version = container.querySelector('[data-testid="model-version"]').value;
    const learningRate = container.querySelector('[data-testid="learning-rate"]').value;

    if (!dataset || !table || !startDate || !endDate || !version) {
      alert('必須項目を入力してください');
      return;
    }

    const progressContainer = container.querySelector('#retraining-progress-container');
    const progressBar = container.querySelector('#retraining-progress-bar');
    const progressPct = container.querySelector('#retraining-progress-pct');
    const statusSpan = container.querySelector('#retraining-status');
    const logDiv = container.querySelector('#training-log');

    progressContainer.style.display = 'block';
    statusSpan.textContent = '実行中';
    logDiv.textContent = `[${new Date().toLocaleTimeString()}] 再学習を開始します...\n`;

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;
      progressBar.style.width = progress + '%';
      progressPct.textContent = Math.floor(progress);

      if (progress === 100) {
        clearInterval(interval);
        statusSpan.textContent = '完了';
        logDiv.textContent += `[${new Date().toLocaleTimeString()}] 再学習が完了しました。\n`;
      }
    }, 800);
  });

  // 精度検証実行
  validationBtn.addEventListener('click', async () => {
    const dataset = container.querySelector('[data-testid="validation-dataset-select"]').value;
    const model = container.querySelector('[data-testid="validation-model-select"]').value;
    const startDate = container.querySelector('[data-testid="validation-start-date"]').value;
    const endDate = container.querySelector('[data-testid="validation-end-date"]').value;

    if (!dataset || !model || !startDate || !endDate) {
      alert('必須項目を入力してください');
      return;
    }

    const progressContainer = container.querySelector('#validation-progress-container');
    const progressBar = container.querySelector('#validation-progress-bar');
    const progressPct = container.querySelector('#validation-progress-pct');
    const statusSpan = container.querySelector('#validation-status');
    const metricsContainer = container.querySelector('#metrics-container');

    progressContainer.style.display = 'block';
    statusSpan.textContent = '実行中';

    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 12;
      if (progress > 100) progress = 100;
      progressBar.style.width = progress + '%';
      progressPct.textContent = Math.floor(progress);

      if (progress === 100) {
        clearInterval(interval);
        statusSpan.textContent = '完了';
        metricsContainer.style.display = 'block';

        // メトリクス表示
        container.querySelector('#metric-accuracy').textContent = '87.5%';
        container.querySelector('#metric-precision').textContent = '89.2%';
        container.querySelector('#metric-recall').textContent = '85.8%';

        // 混同行列描画
        const canvas = container.querySelector('#confusion-matrix-canvas');
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#f8f7f5';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 混同行列セル
        const cellSize = 80;
        const data = [[145, 15], [12, 128]];
        const colors = ['#4a5568', '#2d3748'];

        for (let i = 0; i < 2; i++) {
          for (let j = 0; j < 2; j++) {
            const x = j * cellSize + 10;
            const y = i * cellSize + 10;
            ctx.fillStyle = colors[i === j ? 0 : 1];
            ctx.fillRect(x, y, cellSize - 5, cellSize - 5);
            ctx.fillStyle = '#fff';
            ctx.font = 'bold 16px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(data[i][j], x + cellSize / 2 - 2.5, y + cellSize / 2 - 2.5);
          }
        }
      }
    }, 600);
  });

  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1783330408666');
  });

  cancelBtn.addEventListener('click', () => {
    container.querySelector('[data-testid="training-dataset-select"]').value = '';
    container.querySelector('[data-testid="training-table-select"]').value = '';
    container.querySelector('[data-testid="training-start-date"]').value = '';
    container.querySelector('[data-testid="training-end-date"]').value = '';
    container.querySelector('[data-testid="model-version"]').value = '';
    container.querySelector('[data-testid="learning-rate"]').value = '';
    container.querySelector('[data-testid="validation-dataset-select"]').value = '';
    container.querySelector('[data-testid="validation-model-select"]').value = '';
    container.querySelector('[data-testid="validation-start-date"]').value = '';
    container.querySelector('[data-testid="validation-end-date"]').value = '';
    container.querySelector('#retraining-progress-container').style.display = 'none';
    container.querySelector('#validation-progress-container').style.display = 'none';
    container.querySelector('#metrics-container').style.display = 'none';
  });
}
